from bisect import bisect_right


def regex_search(pattern: str, text: str) -> bool:
    p = pattern
    m = len(p)

    def parse_sequence(stop):
        nonlocal i
        elems = []

        while i < m:
            c = p[i]

            if c == "|":
                break
            if stop is not None and c == stop:
                break
            if stop is None and c == ")":
                raise ValueError("unmatched ')'")
            if c in "*+?":
                raise ValueError("quantifier without preceding element")

            if c == "^":
                elems.append(("anchor", "start"))
                i += 1
                continue

            if c == "$":
                elems.append(("anchor", "end"))
                i += 1
                continue

            if c == "(":
                i += 1
                inner = parse_alternation(")")
                if i >= m or p[i] != ")":
                    raise ValueError("unmatched '('")
                i += 1
                atom = ("group", inner)
            else:
                if c == "\\":
                    if i + 1 >= m:
                        raise ValueError("trailing backslash")
                    ch = p[i + 1]
                    i += 2
                    atom = ("char", ch)
                elif c == ".":
                    i += 1
                    atom = ("dot",)
                elif c == "[":
                    atom = parse_char_class()
                else:
                    i += 1
                    atom = ("char", c)

            if i < m and p[i] in "*+?":
                kind = p[i]
                i += 1
                elems.append(("rep", atom, kind))
            else:
                elems.append(atom)

        return elems

    def parse_alternation(stop):
        alts = [parse_sequence(stop)]

        while i < m and p[i] == "|":
            i += 1
            alts.append(parse_sequence(stop))

        return ("alt", alts)

    def parse_char_class():
        nonlocal i

        i += 1
        negated = False

        if i < m and p[i] == "^":
            negated = True
            i += 1

        if i >= m:
            raise ValueError("unterminated character class")

        ranges = []

        while i < m:
            if p[i] == "]":
                if not ranges:
                    raise ValueError("empty character class")
                break

            if p[i] == "\\":
                if i + 1 >= m:
                    raise ValueError("trailing backslash inside character class")
                lo = p[i + 1]
                j = i + 2
                escaped_lo = True
            else:
                lo = p[i]
                j = i + 1
                escaped_lo = False

            if not escaped_lo and lo == "-":
                ranges.append((ord("-"), ord("-")))
                i = j
                continue

            if (
                j < m
                and p[j] == "-"
                and j + 1 < m
                and p[j + 1] != "]"
            ):
                if p[j + 1] == "\\":
                    if j + 2 >= m:
                        raise ValueError("trailing backslash inside character class")
                    hi = p[j + 2]
                    k = j + 3
                else:
                    hi = p[j + 1]
                    k = j + 2

                if ord(lo) > ord(hi):
                    raise ValueError("invalid range")
                ranges.append((ord(lo), ord(hi)))
                i = k
            else:
                ranges.append((ord(lo), ord(lo)))
                i = j

        if i < m and p[i] == "]":
            i += 1
            return ("class", negated, ranges)

        raise ValueError("unterminated character class")

    i = 0
    ast = parse_alternation(None)
    if i != m:
        raise ValueError("invalid pattern")

    transitions = []

    def new_state():
        transitions.append([])
        return len(transitions) - 1

    def compile_alt(alt_node):
        _, alts = alt_node
        start = new_state()
        end = new_state()

        for seq in alts:
            s, e = compile_seq(seq)
            transitions[start].append(("e", s, 0))
            transitions[e].append(("e", end, 0))

        return start, end

    def compile_seq(seq):
        if not seq:
            s = new_state()
            e = new_state()
            transitions[s].append(("e", e, 0))
            return s, e

        start, end = compile_elem(seq[0])

        for elem in seq[1:]:
            s, e = compile_elem(elem)
            transitions[end].append(("e", s, 0))
            end = e

        return start, end

    def compile_elem(elem):
        kind = elem[0]

        if kind == "char":
            s = new_state()
            e = new_state()
            transitions[s].append(("c", elem[1], e))
            return s, e

        if kind == "dot":
            s = new_state()
            e = new_state()
            transitions[s].append(("a", e))
            return s, e

        if kind == "class":
            _, negated, ranges = elem
            s = new_state()
            e = new_state()
            transitions[s].append(("cl", negated, ranges, e))
            return s, e

        if kind == "group":
            return compile_alt(elem[1])

        if kind == "anchor":
            s = new_state()
            e = new_state()
            cond = 1 if elem[1] == "start" else 2
            transitions[s].append(("e", e, cond))
            return s, e

        if kind == "rep":
            atom, q = elem[1], elem[2]
            b_start, b_end = compile_elem(atom)

            if q == "?":
                s = new_state()
                e = new_state()
                transitions[s].append(("e", b_start, 0))
                transitions[s].append(("e", e, 0))
                transitions[b_end].append(("e", e, 0))
                return s, e

            if q == "*":
                s = new_state()
                e = new_state()
                transitions[s].append(("e", b_start, 0))
                transitions[s].append(("e", e, 0))
                transitions[b_end].append(("e", s, 0))
                return s, e

            # q == "+"
            s = new_state()
            e = new_state()
            transitions[s].append(("e", b_start, 0))
            transitions[b_end].append(("e", s, 0))
            transitions[b_end].append(("e", e, 0))
            return s, e

        raise ValueError("internal AST error")

    start_state, accept_state = compile_alt(ast)

    def normalize_ranges(ranges):
        if not ranges:
            return []
        rs = sorted(ranges)
        merged = []
        lo, hi = rs[0]
        for l, h in rs[1:]:
            if l <= hi + 1:
                if h > hi:
                    hi = h
            else:
                merged.append((lo, hi))
                lo, hi = l, h
        merged.append((lo, hi))
        return merged

    def make_class_matcher(negated, ranges):
        normalized = normalize_ranges(ranges)
        if not normalized:
            if negated:
                return lambda ch: False
            return lambda ch: True

        los = [lo for lo, _ in normalized]

        if negated:
            def match(ch):
                code = ord(ch)
                idx = bisect_right(los, code) - 1
                inside = idx >= 0 and code <= normalized[idx][1]
                return not inside
        else:
            def match(ch):
                code = ord(ch)
                idx = bisect_right(los, code) - 1
                return idx >= 0 and code <= normalized[idx][1]

        return match

    eps_edges = []
    literal_edges = []
    any_edges = []
    class_edges = []

    for state_edges in transitions:
        eps_edges.append([])
        literal_edges.append({})
        any_edges.append([])
        class_edges.append([])

        for tr in state_edges:
            if tr[0] == "e":
                _, to, cond = tr
                eps_edges[len(eps_edges) - 1].append((to, cond))
            elif tr[0] == "c":
                _, ch, to = tr
                literal_edges[len(literal_edges) - 1].setdefault(ch, []).append(to)
            elif tr[0] == "a":
                _, to = tr
                any_edges[len(any_edges) - 1].append(to)
            elif tr[0] == "cl":
                _, negated, ranges, to = tr
                class_edges[len(class_edges) - 1].append(
                    (make_class_matcher(negated, ranges), to)
                )

    def closure(states, pos):
        seen = set(states)
        stack = list(states)

        while stack:
            state = stack.pop()
            for to, cond in eps_edges[state]:
                if cond == 0:
                    ok = True
                elif cond == 1:
                    ok = pos == 0
                else:
                    ok = pos == len(text)

                if ok and to not in seen:
                    seen.add(to)
                    stack.append(to)

        return seen

    pos = 0
    states = set()

    while True:
        states.add(start_state)
        states = closure(states, pos)

        if accept_state in states:
            return True

        if pos == len(text):
            break

        ch = text[pos]
        nxt = set()

        for state in states:
            if ch in literal_edges[state]:
                for to in literal_edges[state][ch]:
                    nxt.add(to)

            for to in any_edges[state]:
                nxt.add(to)

            for matcher, to in class_edges[state]:
                if matcher(ch):
                    nxt.add(to)

        pos += 1
        states = nxt

    return False
